// Command fiz is a standalone CLI that wraps the fizeau library.
package main

import (
	"fmt"
	"os"

	"github.com/easel/fizeau/agentcli"
	"github.com/easel/fizeau/internal/buildinfo"
)

// Version info set via -ldflags.
var (
	Version   = "dev"
	BuildTime = ""
	GitCommit = ""
)

func main() {
	bi := buildinfo.Read(Version, GitCommit, BuildTime)
	cmd := agentcli.MountCLI(
		agentcli.WithStdin(os.Stdin),
		agentcli.WithStdout(os.Stdout),
		agentcli.WithStderr(os.Stderr),
		agentcli.WithVersion(bi.Version, bi.Built, bi.Commit),
	)
	args := os.Args[1:]
	if agentcli.NeedsLegacyPassthrough(args) {
		args = append([]string{"--"}, args...)
	}
	cmd.SetArgs(args)
	if err := cmd.Execute(); err != nil {
		if code, ok := agentcli.ExitCode(err); ok {
			os.Exit(code)
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

// effectiveVersion returns version from ldflags when set, otherwise falls back
// to the module version from runtime build info.
func effectiveVersion(defaultVersion string) string {
	return buildinfo.Read(defaultVersion, "", "").Version
}

package main

import (
	"bytes"
	"encoding/json"
	"os"
	"strings"
	"testing"

	"github.com/easel/fizeau/agentcli"
	"github.com/easel/fizeau/internal/buildinfo"
)

// TestRouteStatusCommandJSON verifies that fiz route-status --help documents
// all routing-evidence flags that operators need for --json inspection:
// --json (output mode), --policy, --min-power, --max-power (power policy),
// --model, --provider (pin constraints).
// This confirms AC-2 of FEAT-004: the route-status command surfaces the JSON
// evidence envelope via its documented flag set.
func TestRouteStatusCommandJSON(t *testing.T) {
	var stdout, stderr bytes.Buffer
	cmd := agentcli.MountCLI(
		agentcli.WithStdout(&stdout),
		agentcli.WithStderr(&stderr),
	)
	cmd.SetArgs([]string{"route-status", "--help"})
	_ = cmd.Execute()

	help := stdout.String() + stderr.String()
	for _, flag := range []string{"--json", "--policy", "--min-power", "--max-power", "--model", "--provider"} {
		if !strings.Contains(help, flag) {
			t.Errorf("route-status help missing routing-evidence flag %q:\n%s", flag, help)
		}
	}
	// Legacy model names must not appear in help: the target surface is power-based routing.
	for _, legacy := range []string{"code-high", "code-medium"} {
		if strings.Contains(help, legacy) {
			t.Errorf("route-status help must not mention legacy name %q:\n%s", legacy, help)
		}
	}
}

// TestListModelsCommandJSON verifies that fiz --list-models --json is a
// documented flag path in the root command, confirming AC-1 of FEAT-004:
// list-models JSON output includes the routing metadata fields operators need.
func TestListModelsCommandJSON(t *testing.T) {
	var stdout, stderr bytes.Buffer
	cmd := agentcli.MountCLI(
		agentcli.WithStdout(&stdout),
		agentcli.WithStderr(&stderr),
	)
	cmd.SetArgs([]string{"--help"})
	_ = cmd.Execute()

	help := stdout.String() + stderr.String()
	for _, flag := range []string{"--list-models", "--json"} {
		if !strings.Contains(help, flag) {
			t.Errorf("fiz --help missing flag %q:\n%s", flag, help)
		}
	}
}

// TestRouteStatusJSONOutputSchema verifies the stable JSON envelope shape that
// route-status --json emits when no providers are configured. Even with a
// routing error, the envelope must include all documented top-level keys so
// operator tooling can parse it unconditionally.
func TestRouteStatusJSONOutputSchema(t *testing.T) {
	workDir := t.TempDir()
	// Write minimal config (no providers) so the service can be instantiated.
	cfgPath := workDir + "/.fizeau.yaml"
	if err := os.WriteFile(cfgPath, []byte("providers: {}\n"), 0o644); err != nil {
		t.Fatalf("write config: %v", err)
	}

	var stdout, stderr bytes.Buffer
	cmd := agentcli.MountCLI(
		agentcli.WithStdout(&stdout),
		agentcli.WithStderr(&stderr),
	)
	// Invoke route-status --json with the temp work dir.
	// No providers → routing will fail, but the JSON envelope is always emitted.
	cmd.SetArgs([]string{"--work-dir", workDir, "--json", "route-status"})
	_ = cmd.Execute()

	out := stdout.String()
	if out == "" {
		t.Skip("route-status produced no stdout (possible permission or config issue); skip schema check")
	}

	// The output must be valid JSON.
	var envelope map[string]json.RawMessage
	if err := json.Unmarshal([]byte(strings.TrimSpace(out)), &envelope); err != nil {
		t.Fatalf("route-status --json output is not valid JSON: %v\noutput: %s", err, out)
	}

	// Required top-level keys per AC-2 of FEAT-004.
	for _, key := range []string{"candidates", "power_policy"} {
		if _, ok := envelope[key]; !ok {
			t.Errorf("route-status JSON envelope missing required key %q:\n%s", key, out)
		}
	}
}

func TestEffectiveVersionKeepsStampedVersion(t *testing.T) {
	if got := effectiveVersion("v1.2.3"); got != "v1.2.3" {
		t.Fatalf("effectiveVersion(stamped) = %q, want stamped version", got)
	}
}

func TestEffectiveVersionDevFallback(t *testing.T) {
	// "dev" is the sentinel for missing ldflags; the function must return a
	// non-empty string — either "dev" (no VCS info) or a module version.
	got := effectiveVersion("dev")
	if got == "" {
		t.Fatal("effectiveVersion(dev) returned empty string")
	}
}

// TestVersionFlagOutputsNonEmptyCommit verifies that when buildinfo.Read finds
// a VCS commit (as it does during go run from a git checkout), the --version
// flag outputs it rather than an empty field. Uses buildinfo.Read directly to
// simulate what main() does — test binaries may not embed VCS info, so the
// test skips when no commit is available.
func TestVersionFlagOutputsNonEmptyCommit(t *testing.T) {
	bi := buildinfo.Read("dev", "", "")
	if bi.Commit == "" {
		t.Skip("no VCS commit info in test binary; skipping (pass with go run)")
	}

	var stdout bytes.Buffer
	cmd := agentcli.MountCLI(
		agentcli.WithStdout(&stdout),
		agentcli.WithVersion(bi.Version, bi.Built, bi.Commit),
	)
	cmd.SetArgs([]string{"--version"})
	_ = cmd.Execute()
	out := stdout.String()
	if strings.Contains(out, "commit ,") {
		t.Errorf("--version output has empty commit field: %q", out)
	}
}

func TestProfileHelpAvoidsLegacyCodeHighAndCodeMedium(t *testing.T) {
	var stdout, stderr bytes.Buffer
	cmd := agentcli.MountCLI(
		agentcli.WithStdout(&stdout),
		agentcli.WithStderr(&stderr),
	)
	cmd.SetArgs([]string{"route-status", "--help"})
	if err := cmd.Execute(); err != nil {
		t.Fatalf("Execute: %v", err)
	}

	help := stdout.String() + stderr.String()
	for _, want := range []string{"--policy", "--min-power", "--max-power"} {
		if !strings.Contains(help, want) {
			t.Fatalf("help output missing %q:\n%s", want, help)
		}
	}
	for _, legacy := range []string{"code-high", "code-medium"} {
		if strings.Contains(help, legacy) {
			t.Fatalf("help output must not mention %q:\n%s", legacy, help)
		}
	}
}

package modelregistry

import (
	"time"

	"github.com/easel/fizeau/internal/modelcatalog"
)

// Source records how a model ID was discovered.
type Source string

const (
	SourceNativeAPI  Source = "native_api"
	SourceHarnessPTY Source = "harness_pty"
	SourcePropsAPI   Source = "props_api"
)

// ModelStatus records the provider runtime state relevant to routing.
type ModelStatus string

const (
	StatusAvailable   ModelStatus = "available"
	StatusRateLimited ModelStatus = "rate_limited"
	StatusUnreachable ModelStatus = "unreachable"
	StatusUnknown     ModelStatus = "unknown"
)

// KnownModel is one discovered provider/model identity enriched with catalog
// metadata when the catalog knows the model.
type KnownModel struct {
	Provider string
	ID       string

	DiscoveredVia Source
	DiscoveredAt  time.Time

	Family     string
	Version    []int
	Tier       modelcatalog.Tier
	PreRelease bool

	Power           int
	CostInputPerM   float64
	CostOutputPerM  float64
	ContextWindow   int
	ReasoningLevels []string
	QuotaPool       string

	Status          ModelStatus
	AutoRoutable    bool
	ExclusionReason string
}

// ModelSnapshot is the in-memory model registry view assembled from discovery
// cache entries and catalog metadata.
type ModelSnapshot struct {
	Models  []KnownModel
	AsOf    time.Time
	Sources map[string]SourceMeta
}

// SourceMeta summarizes cache state for a discovery source.
type SourceMeta struct {
	LastRefreshedAt time.Time
	Stale           bool
	Error           string
}
package modelregistry

import (
	"context"
	"os/exec"
	"sort"

	"github.com/easel/fizeau/internal/config"
	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/modelcatalog"
)

// Assemble builds a ModelSnapshot from configured providers, cache-backed
// discovery, runtime status cache state, and model catalog metadata.
func Assemble(ctx context.Context, cfg *config.Config, cat *modelcatalog.Catalog, cache *discoverycache.Cache) (ModelSnapshot, error) {
	asOf := nowUTC()
	snapshot := ModelSnapshot{
		AsOf:    asOf,
		Sources: map[string]SourceMeta{},
	}
	if cfg == nil {
		return snapshot, nil
	}

	providers := enumerateProviders(cfg)
	names := make([]string, 0, len(providers))
	for name := range providers {
		names = append(names, name)
	}
	sort.Strings(names)

	for _, providerName := range names {
		pcfg := providers[providerName]
		discovered := discoverProvider(ctx, providerName, pcfg, cache)
		for source, meta := range discovered.Sources {
			snapshot.Sources[source] = meta
		}
		includeByDefault := effectiveProviderIncludeByDefault(providerName, pcfg, cat)
		status := providerStatus(cache, providerName)
		for _, discoveredModel := range discovered.Models {
			model := KnownModel{
				Provider:      providerName,
				ID:            discoveredModel.ID,
				DiscoveredVia: discoveredModel.Via,
				DiscoveredAt:  discoveredModel.DiscoveredAt,
				Status:        status,
			}
			snapshot.Models = append(snapshot.Models, enrichModel(model, includeByDefault, cat))
		}
	}
	sort.Slice(snapshot.Models, func(i, j int) bool {
		if snapshot.Models[i].Provider != snapshot.Models[j].Provider {
			return snapshot.Models[i].Provider < snapshot.Models[j].Provider
		}
		return snapshot.Models[i].ID < snapshot.Models[j].ID
	})
	return snapshot, nil
}

func enumerateProviders(cfg *config.Config) map[string]config.ProviderConfig {
	out := make(map[string]config.ProviderConfig, len(cfg.Providers)+2)
	for name, pc := range cfg.Providers {
		out[name] = pc
	}
	addImplicitHarness(out, "claude-subscription", "claude", "claude")
	addImplicitHarness(out, "codex-subscription", "codex", "codex")
	return out
}

func addImplicitHarness(providers map[string]config.ProviderConfig, name, providerType, binary string) {
	if _, exists := providers[name]; exists {
		return
	}
	if _, err := exec.LookPath(binary); err != nil {
		return
	}
	include := true
	providers[name] = config.ProviderConfig{
		Type:             providerType,
		IncludeByDefault: &include,
		Billing:          string(modelcatalog.BillingModelSubscription),
	}
}

// Package discoverycache implements the per-source on-disk cache described in
// ADR-012. It provides a two-tier lock + long-lived refresh marker pattern so
// that slow discovery IO (PTY ~30 s, HTTP ~316 ms) never blocks UI reads.
//
// Public surface: Cache.Read, Cache.Refresh, Cache.MaybeRefresh, Cache.Prune.
// The Refresher function is injected; the cache manages single-flight
// deduplication, atomic writes, and crash recovery.
package discoverycache

import (
	"context"
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"

	"golang.org/x/sync/singleflight"
)

const (
	lockAcquisitionTimeout = 100 * time.Millisecond
	lockPollInterval       = 5 * time.Millisecond
	waitPollInterval       = 250 * time.Millisecond
	stalenessMultiplier    = time.Duration(2)
)

// Cache is the root handle. Root is the base directory (e.g. ~/.cache/fizeau).
// Each Cache instance owns one in-process singleflight.Group; a new Cache per
// process is the normal usage.
type Cache struct {
	Root string
	sf   singleflight.Group
}

// Source describes one cacheable data stream (one file under Root/Tier/Name.json).
type Source struct {
	// Tier is "discovery" or "runtime".
	Tier string
	// Name is the kebab-case source identifier (e.g. "openrouter").
	Name string
	// TTL controls freshness: Read returns Fresh=true when Age < TTL.
	TTL time.Duration
	// RefreshDeadline is the maximum time a refresh is expected to take.
	// Also controls the staleness threshold: 2 × RefreshDeadline.
	RefreshDeadline time.Duration
}

func (s Source) key() string { return s.Tier + "/" + s.Name }

// ReadResult is the output of Cache.Read.
type ReadResult struct {
	// Data is the raw bytes from the cache file; nil if no file exists.
	Data []byte
	// Age is how long ago the data was written (0 if absent).
	Age time.Duration
	// Fresh is true when Age < TTL and Data is non-nil.
	Fresh bool
	// Stale is true when Data is nil or Age >= TTL.
	Stale bool
}

// Refresher is the source-fetch function injected by the caller. The cache
// handles single-flight deduplication, the atomic write, and marker lifecycle.
type Refresher func(ctx context.Context) ([]byte, error)

// Read returns cached data without any IO beyond reading the local file.
// It never blocks on network or PTY. If no cache file exists, Data is nil and
// Stale is true. Stale data is always returned without error; the caller
// decides whether to trigger a background refresh.
func (c *Cache) Read(s Source) (ReadResult, error) {
	path := c.dataPath(s)
	data, err := os.ReadFile(path) // #nosec G304
	if errors.Is(err, os.ErrNotExist) {
		return ReadResult{Stale: true}, nil
	}
	if err != nil {
		return ReadResult{}, err
	}
	info, err := os.Stat(path)
	if err != nil {
		// File was just there; best-effort fallback.
		return ReadResult{Data: data, Stale: true}, nil
	}
	age := time.Since(info.ModTime())
	if age < 0 {
		age = 0
	}
	fresh := age < s.TTL
	return ReadResult{
		Data:  data,
		Age:   age,
		Fresh: fresh,
		Stale: !fresh,
	}, nil
}

// Prune removes data files (and their sidecar lock/marker/tmp files) for
// sources not listed in activeSources. Sources with an active .refreshing
// marker are skipped. Prune acquires the tier-1 lock before removing each
// source's files.
func (c *Cache) Prune(activeSources []Source) error {
	active := make(map[string]bool, len(activeSources))
	for _, s := range activeSources {
		active[s.key()] = true
	}

	return filepath.WalkDir(c.Root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return nil
		}
		if !strings.HasSuffix(d.Name(), ".json") {
			return nil
		}
		rel, rerr := filepath.Rel(c.Root, path)
		if rerr != nil {
			return nil
		}
		parts := strings.SplitN(rel, string(filepath.Separator), 2)
		if len(parts) != 2 {
			return nil
		}
		tier := parts[0]
		name := strings.TrimSuffix(parts[1], ".json")
		if strings.ContainsRune(name, filepath.Separator) {
			return nil // nested dir, skip
		}

		if active[tier+"/"+name] {
			return nil
		}

		s := Source{Tier: tier, Name: name}

		// Skip sources with an active refresh in progress.
		m, _ := readMarker(c.markerPath(s))
		if isMarkerActiveForPrune(m) {
			return nil
		}

		release, lerr := c.acquireLock(s)
		if lerr != nil {
			return nil // can't lock; skip this source
		}
		defer release()

		// Re-check under lock.
		m2, _ := readMarker(c.markerPath(s))
		if isMarkerActiveForPrune(m2) {
			return nil
		}

		_ = os.Remove(c.dataPath(s))
		_ = os.Remove(c.markerPath(s))
		_ = os.Remove(c.tmpPath(s))
		return nil
	})
}

// ---- internal ---------------------------------------------------------------

type claimResult struct {
	claimed bool
	marker  *refreshMarker
}

// claimRefresh implements Algorithm 1 from ADR-012. Must be called with the
// source directory already created (ensured by refreshAndCommit).
func (c *Cache) claimRefresh(s Source) (claimResult, error) {
	release, err := c.acquireLock(s)
	if err != nil {
		return claimResult{}, err
	}
	defer release()

	existing, _ := readMarker(c.markerPath(s))
	if existing != nil {
		if isStale(s, existing) {
			_ = os.Remove(c.markerPath(s))
		} else {
			return claimResult{claimed: false, marker: existing}, nil
		}
	}

	m := &refreshMarker{
		PID:       os.Getpid(),
		StartedAt: time.Now().UTC(),
		Deadline:  time.Now().UTC().Add(s.RefreshDeadline),
	}
	if werr := writeMarker(c.markerPath(s), m); werr != nil {
		return claimResult{}, werr
	}
	return claimResult{claimed: true}, nil
}

// refreshAndCommit implements Algorithm 2 from ADR-012.
func (c *Cache) refreshAndCommit(s Source, fn Refresher) error {
	if err := os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750); err != nil {
		return err
	}

	claim, err := c.claimRefresh(s)
	if err != nil {
		return err
	}
	if !claim.claimed {
		// Another process is refreshing; wait for it.
		return c.waitForRefresh(s, claim.marker)
	}

	// We hold the claim. Run slow IO outside any lock.
	data, fetchErr := fn(context.Background())
	if fetchErr != nil {
		c.releaseMarker(s)
		return fetchErr
	}

	if werr := atomicWrite(c.dataPath(s), data); werr != nil {
		c.releaseMarker(s)
		return werr
	}

	c.releaseMarker(s)
	return nil
}

// waitForRefresh implements Algorithm 3 from ADR-012. Polls until the marker
// disappears or becomes stale, then returns (data has been written).
func (c *Cache) waitForRefresh(s Source, m *refreshMarker) error {
	// Poll until deadline + staleness_threshold or s.RefreshDeadline, whichever first.
	threshold := s.RefreshDeadline * stalenessMultiplier
	absoluteDeadline := m.Deadline.Add(threshold)
	maxWait := time.Now().Add(s.RefreshDeadline)
	if maxWait.Before(absoluteDeadline) {
		absoluteDeadline = maxWait
	}

	for time.Now().Before(absoluteDeadline) {
		time.Sleep(waitPollInterval)
		current, _ := readMarker(c.markerPath(s))
		if current == nil || isStale(s, current) {
			return nil
		}
	}
	return nil // timed out; caller will read whatever is on disk
}

// releaseMarker removes the .refreshing marker under the tier-1 lock, but
// only if our PID is still recorded (guard against PID-reuse races, per §2
// of refreshAndCommit pseudocode in ADR-012).
func (c *Cache) releaseMarker(s Source) {
	release, err := c.acquireLock(s)
	if err != nil {
		return
	}
	defer release()
	m, _ := readMarker(c.markerPath(s))
	if m != nil && m.PID == os.Getpid() {
		_ = os.Remove(c.markerPath(s))
// Package runtimesignals collects volatile per-provider runtime signals
// (status, quota remaining, recent p50 latency) and writes them to the
// runtime tier of M1's per-source on-disk cache (ADR-012). M2's snapshot
// assembler reads the cache files to populate KnownModel.Status,
// .QuotaRemaining, and .RecentP50Latency.
package runtimesignals

import "time"

// ModelStatus represents the operational availability of a provider.
type ModelStatus string

const (
	StatusAvailable ModelStatus = "available"
	StatusDegraded  ModelStatus = "degraded"
	StatusExhausted ModelStatus = "exhausted"
	StatusUnknown   ModelStatus = "unknown"
)

// Signal is the runtime state snapshot for one provider. It is serialized as
// JSON to runtime/<provider>.json in M1's cache directory.
type Signal struct {
	Provider         string        `json:"provider"`
	Status           ModelStatus   `json:"status"`
	QuotaRemaining   *int          `json:"quota_remaining,omitempty"`
	QuotaResetAt     *time.Time    `json:"quota_reset_at,omitempty"`
	RecentP50Latency time.Duration `json:"recent_p50_latency_ns"`
	LastSuccessAt    *time.Time    `json:"last_success_at,omitempty"`
	LastErrorAt      *time.Time    `json:"last_error_at,omitempty"`
	LastErrorMsg     string        `json:"last_error_msg,omitempty"`
	RecordedAt       time.Time     `json:"recorded_at"`
}

package modelregistry

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/easel/fizeau/internal/config"
	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/modelref"
	openaiadapter "github.com/easel/fizeau/internal/provider/openai"
)

const (
	discoveryTTLHTTPRemote       = 24 * time.Hour
	discoveryTTLHTTPLocal        = time.Hour
	discoveryTTLPTY              = 24 * time.Hour
	discoveryRefreshDeadlineHTTP = 10 * time.Second
	discoveryRefreshDeadlinePTY  = 60 * time.Second
)

type discoveredModel struct {
	ID           string
	Via          Source
	DiscoveredAt time.Time
}

type providerDiscoveryResult struct {
	Models  []discoveredModel
	Sources map[string]SourceMeta
}

type discoveryPayload struct {
	CapturedAt      time.Time `json:"captured_at"`
	Models          []string  `json:"models,omitempty"`
	ReasoningLevels []string  `json:"reasoning_levels,omitempty"`
	Source          string    `json:"source,omitempty"`
}

func discoverProvider(ctx context.Context, providerName string, pc config.ProviderConfig, cache *discoverycache.Cache) providerDiscoveryResult {
	providerType := normalizeProviderType(pc.Type)
	switch providerType {
	case "claude", "codex":
		return discoverHarnessProvider(providerName, providerType, cache)
	case "openai", "openrouter", "vidar-ds4", "sindri-llamacpp", "ds4", "lmstudio", "llama-server", "omlx", "rapid-mlx", "vllm", "ollama", "minimax", "qwen", "zai":
		result := discoverOpenAICompatibleProvider(ctx, providerName, pc, cache)
		if providerType == "ds4" || providerType == "vidar-ds4" {
			result.merge(discoverPropsProvider(providerName, cache))
		}
		return result
	default:
		if strings.TrimSpace(pc.Model) == "" {
			return providerDiscoveryResult{Sources: map[string]SourceMeta{}}
		}
		return providerDiscoveryResult{
			Models: []discoveredModel{{
				ID:           strings.TrimSpace(pc.Model),
				Via:          SourceNativeAPI,
				DiscoveredAt: time.Now().UTC(),
			}},
			Sources: map[string]SourceMeta{
				providerName: {LastRefreshedAt: time.Now().UTC()},
			},
		}
	}
}

func discoverOpenAICompatibleProvider(ctx context.Context, providerName string, pc config.ProviderConfig, cache *discoverycache.Cache) providerDiscoveryResult {
	src := discoverySource(providerName, discoveryTTLForProvider(pc), discoveryRefreshDeadlineHTTP)
	if cache == nil {
		return providerDiscoveryResult{Sources: map[string]SourceMeta{providerName: {Stale: true, Error: "discovery cache is nil"}}}
	}
	result := readDiscoveryCache(cache, src, providerName, SourceNativeAPI)
	if result.Sources == nil {
		result.Sources = map[string]SourceMeta{}
	}
	if hasDiscoveryEndpoint(pc) {
		baseURL := strings.TrimRight(firstBaseURL(pc), "/")
		apiKey := pc.APIKey
		cache.MaybeRefresh(src, func(refreshCtx context.Context) ([]byte, error) {
			requestCtx := ctx
			if requestCtx == nil {
				requestCtx = refreshCtx
			}
			ids, err := openaiadapter.DiscoverModels(requestCtx, baseURL, apiKey)
			if err != nil {
				return nil, err
			}
			return json.Marshal(discoveryPayload{
				CapturedAt: time.Now().UTC(),
				Models:     ids,
				Source:     "openai-compatible:/v1/models",
			})
		})
		_ = ctx
	}
	return result
}

func discoverPropsProvider(providerName string, cache *discoverycache.Cache) providerDiscoveryResult {
	if cache == nil {
		return providerDiscoveryResult{Sources: map[string]SourceMeta{providerName + ":props": {Stale: true, Error: "discovery cache is nil"}}}
	}
	src := discoverySource(providerName+"-props", discoveryTTLHTTPLocal, discoveryRefreshDeadlineHTTP)
	result := readDiscoveryCache(cache, src, providerName, SourcePropsAPI)
	renamed := make(map[string]SourceMeta, len(result.Sources))
	for _, meta := range result.Sources {
		renamed[providerName+":props"] = meta
	}
	result.Sources = renamed
	return result
}

func discoverHarnessProvider(providerName, providerType string, cache *discoverycache.Cache) providerDiscoveryResult {
	src := discoverycache.Source{
		Tier:            "discovery",
		Name:            providerName,
		TTL:             discoveryTTLPTY,
		RefreshDeadline: discoveryRefreshDeadlinePTY,
	}
	if cache == nil {
		snapshot, err := harnesses.CachedModelDiscoverySnapshot(providerType, harnesses.EmbeddedDiscoverySource)
		if err != nil {
			return providerDiscoveryResult{Sources: map[string]SourceMeta{providerName: {Stale: true, Error: err.Error()}}}
		}
		return modelsFromIDs(snapshot.Models, SourceHarnessPTY, snapshot.CapturedAt, providerName)
	}
	result := readDiscoveryCache(cache, src, providerName, SourceHarnessPTY)
	if len(result.Models) > 0 {
		return result
	}
	snapshot, err := harnesses.CachedModelDiscoverySnapshot(providerType, harnesses.EmbeddedDiscoverySource)
	if err != nil {
		if result.Sources == nil {
			result.Sources = map[string]SourceMeta{}
		}
		meta := result.Sources[providerName]
		meta.Error = err.Error()
		result.Sources[providerName] = meta
		return result
	}
	return modelsFromIDs(snapshot.Models, SourceHarnessPTY, snapshot.CapturedAt, providerName)
}

func readDiscoveryCache(cache *discoverycache.Cache, src discoverycache.Source, providerName string, via Source) providerDiscoveryResult {
	result := providerDiscoveryResult{Sources: map[string]SourceMeta{}}
	read, err := cache.Read(src)
	meta := SourceMeta{Stale: true}
	if read.Data != nil {
		meta.LastRefreshedAt = time.Now().Add(-read.Age).UTC()
		meta.Stale = read.Stale
	}
	if err != nil {
		meta.Error = err.Error()
		result.Sources[src.Name] = meta
		return result
	}
	result.Sources[src.Name] = meta
	if read.Data == nil {
		return result
	}
	ids, capturedAt, err := parseDiscoveryIDs(read.Data, providerName)
	if err != nil {
		meta.Error = err.Error()
		result.Sources[src.Name] = meta
		return result
	}
	if !capturedAt.IsZero() {
		meta.LastRefreshedAt = capturedAt.UTC()
		result.Sources[src.Name] = meta
	}
	result.Models = modelsFromIDs(ids, via, discoveredAt(capturedAt, meta.LastRefreshedAt), providerName).Models
	return result
}

func parseDiscoveryIDs(data []byte, providerName string) ([]string, time.Time, error) {
	data = bytes.TrimSpace(data)
	if len(data) == 0 {
		return nil, time.Time{}, nil
	}
	var list []string
	if err := json.Unmarshal(data, &list); err == nil {
		return uniqueSortedStrings(list), time.Time{}, nil
	}
	var payload discoveryPayload
	if err := json.Unmarshal(data, &payload); err == nil && (len(payload.Models) > 0 || !payload.CapturedAt.IsZero()) {
		return uniqueSortedStrings(payload.Models), payload.CapturedAt, nil
	}
	var byRef map[string]json.RawMessage
	if err := json.Unmarshal(data, &byRef); err != nil {
		return nil, time.Time{}, fmt.Errorf("decode discovery cache: %w", err)
	}
	ids := make([]string, 0, len(byRef))
	var capturedAt time.Time
	for key, raw := range byRef {
		includeValueFields := true
		if ref, err := modelref.Parse(key); err == nil {
			includeValueFields = ref.Provider == providerName
			if ref.Provider == providerName {
				ids = append(ids, ref.ID)
			}
		}
		if !includeValueFields {
			continue
		}
		var item struct {
			ID         string    `json:"id"`
			ModelID    string    `json:"model_id"`
			CapturedAt time.Time `json:"captured_at"`
		}
		if err := json.Unmarshal(raw, &item); err == nil {
			if item.ID != "" {
				ids = append(ids, item.ID)
			}
			if item.ModelID != "" {
				ids = append(ids, item.ModelID)
			}
			if capturedAt.IsZero() && !item.CapturedAt.IsZero() {
				capturedAt = item.CapturedAt
			}
		}
	}
	return uniqueSortedStrings(ids), capturedAt, nil
}

func modelsFromIDs(ids []string, via Source, at time.Time, providerName string) providerDiscoveryResult {
	at = discoveredAt(at, time.Now().UTC())
	out := make([]discoveredModel, 0, len(ids))
	seen := make(map[string]bool, len(ids))
	for _, id := range ids {
		id = strings.TrimSpace(id)
		if id == "" || seen[id] {
			continue
		}
		seen[id] = true
		out = append(out, discoveredModel{ID: id, Via: via, DiscoveredAt: at})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return providerDiscoveryResult{
		Models:  out,
		Sources: map[string]SourceMeta{providerName: {LastRefreshedAt: at}},
	}
}

func (r *providerDiscoveryResult) merge(other providerDiscoveryResult) {
	if r.Sources == nil {
		r.Sources = map[string]SourceMeta{}
	}
	for k, v := range other.Sources {
		r.Sources[k] = v
	}
	seen := make(map[string]bool, len(r.Models)+len(other.Models))
	for _, model := range r.Models {
		seen[model.ID] = true
	}
	for _, model := range other.Models {
		if seen[model.ID] {
			continue
		}
		seen[model.ID] = true
		r.Models = append(r.Models, model)
	}
	sort.Slice(r.Models, func(i, j int) bool { return r.Models[i].ID < r.Models[j].ID })
}

func discoverySource(name string, ttl, deadline time.Duration) discoverycache.Source {
	return discoverycache.Source{Tier: "discovery", Name: name, TTL: ttl, RefreshDeadline: deadline}
}

func discoveryTTLForProvider(pc config.ProviderConfig) time.Duration {
	switch normalizeProviderType(pc.Type) {
	case "ds4", "vidar-ds4", "sindri-llamacpp", "lmstudio", "llama-server", "omlx", "rapid-mlx", "vllm", "ollama":
		return discoveryTTLHTTPLocal
	default:
		return discoveryTTLHTTPRemote
	}
}

func hasDiscoveryEndpoint(pc config.ProviderConfig) bool {
	return firstBaseURL(pc) != ""
}

func firstBaseURL(pc config.ProviderConfig) string {
	if strings.TrimSpace(pc.BaseURL) != "" {
		return strings.TrimSpace(pc.BaseURL)
	}
	for _, ep := range pc.Endpoints {
		if strings.TrimSpace(ep.BaseURL) != "" {
			return strings.TrimSpace(ep.BaseURL)
		}
	}
	return ""
}

func discoveredAt(primary, fallback time.Time) time.Time {
	if !primary.IsZero() {
		return primary.UTC()
	}
	if !fallback.IsZero() {
		return fallback.UTC()
	}
	return time.Now().UTC()
}

func uniqueSortedStrings(values []string) []string {
	seen := map[string]bool{}
	out := make([]string, 0, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" || seen[value] {
			continue
		}
		seen[value] = true
		out = append(out, value)
	}

