func runMounted(cfg mountConfig, args []string) error {
	code := Run(Options{
		Args:      args,
		Stdin:     cfg.stdin,
		Stdout:    cfg.stdout,
		Stderr:    cfg.stderr,
		Version:   cfg.version,
		BuildTime: cfg.buildTime,
		GitCommit: cfg.gitCommit,
	})
	if code == 0 {
		return nil
	}
	return &ExitError{Code: code}
}

